"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[751],{7751:(e,a,s)=>{s.d(a,{Pd:()=>i,XD:()=>n,tb:()=>o});let o=[{id:"vagas-suspeitas",title:{pt:"Como identificar vagas suspeitas",en:"How to spot suspicious job offers",es:"C\xf3mo identificar vacantes sospechosas"},intro:{pt:"Golpes com falsas vagas remotas s\xe3o comuns. Alguns sinais merecem aten\xe7\xe3o redobrada.",en:"Scams with fake remote jobs are common. Some signs deserve extra attention.",es:"Las estafas con falsas vacantes remotas son comunes. Algunas se\xf1ales merecen atenci\xf3n especial."},items:[{pt:"Pedido de pagamento para participar do processo seletivo, treinamento ou compra de equipamento.",en:"Requests for payment to join the hiring process, for training or to buy equipment.",es:"Pedidos de pago para participar del proceso de selecci\xf3n, capacitaci\xf3n o compra de equipos."},{pt:"Sal\xe1rio muito acima do mercado para pouca experi\xeancia ou poucas horas.",en:"Pay far above market rates for little experience or few hours.",es:"Salario muy por encima del mercado para poca experiencia o pocas horas."},{pt:"Contato apenas por aplicativos de mensagem, sem e-mail corporativo ou site verific\xe1vel.",en:"Contact only through messaging apps, with no company email or verifiable website.",es:"Contacto solo por apps de mensajer\xeda, sin correo corporativo ni sitio verificable."},{pt:"Pressa para decidir e pedido de documentos ou dados banc\xe1rios antes de uma entrevista.",en:"Pressure to decide quickly and requests for documents or bank details before an interview.",es:"Prisa para decidir y pedido de documentos o datos bancarios antes de una entrevista."},{pt:"Descri\xe7\xe3o vaga da fun\xe7\xe3o e da empresa. Pesquise o nome da empresa e de quem recruta.",en:"Vague role and company descriptions. Search the company's and recruiter's names.",es:"Descripci\xf3n vaga del puesto y de la empresa. Busca el nombre de la empresa y de quien recluta."}]},{id:"moradia",title:{pt:"Como avaliar informa\xe7\xf5es de moradia",en:"How to evaluate housing information",es:"C\xf3mo evaluar informaci\xf3n de vivienda"},intro:{pt:"An\xfancios falsos e expectativas irreais podem comprometer o or\xe7amento e a seguran\xe7a.",en:"Fake listings and unrealistic expectations can compromise your budget and safety.",es:"Los anuncios falsos y las expectativas irreales pueden comprometer el presupuesto y la seguridad."},items:[{pt:"Prefira plataformas com avalia\xe7\xf5es e prote\xe7\xe3o ao pagamento. Evite transfer\xeancias diretas para desconhecidos.",en:"Prefer platforms with reviews and payment protection. Avoid direct transfers to strangers.",es:"Prefiere plataformas con rese\xf1as y protecci\xf3n de pago. Evita transferencias directas a desconocidos."},{pt:"Pe\xe7a uma chamada de v\xeddeo mostrando o im\xf3vel e teste a internet no local, se poss\xedvel.",en:"Ask for a video call showing the place and test the internet there, if possible.",es:"Pide una videollamada mostrando el lugar y prueba el internet all\xed, si es posible."},{pt:"Confira o bairro em diferentes hor\xe1rios e fontes, n\xe3o apenas nas fotos do an\xfancio.",en:"Check the neighborhood at different times and from different sources, not just the listing photos.",es:"Revisa el barrio en distintos horarios y fuentes, no solo en las fotos del anuncio."},{pt:"Leia as regras de cancelamento, cau\xe7\xe3o e o que est\xe1 incluso no valor.",en:"Read the cancellation and deposit rules and what the price includes.",es:"Lee las reglas de cancelaci\xf3n, dep\xf3sito y lo que incluye el precio."}]},{id:"dados-pessoais",title:{pt:"Como proteger seus dados pessoais",en:"How to protect your personal data",es:"C\xf3mo proteger tus datos personales"},intro:{pt:"Trabalhar de redes p\xfablicas e lidar com documentos em viagem exige cuidados digitais.",en:"Working on public networks and handling documents while traveling requires digital care.",es:"Trabajar desde redes p\xfablicas y manejar documentos de viaje exige cuidados digitales."},items:[{pt:"Ative autentica\xe7\xe3o em dois fatores e use um gerenciador de senhas.",en:"Turn on two-factor authentication and use a password manager.",es:"Activa la autenticaci\xf3n en dos pasos y usa un gestor de contrase\xf1as."},{pt:"Evite acessar contas banc\xe1rias em redes Wi-Fi p\xfablicas sem prote\xe7\xe3o.",en:"Avoid accessing bank accounts on unprotected public Wi-Fi.",es:"Evita acceder a cuentas bancarias en redes Wi-Fi p\xfablicas sin protecci\xf3n."},{pt:"N\xe3o publique fotos de passaporte, cart\xf5es de embarque ou endere\xe7o onde est\xe1 hospedado.",en:"Don't post photos of your passport, boarding passes or where you're staying.",es:"No publiques fotos del pasaporte, tarjetas de embarque o la direcci\xf3n donde te alojas."},{pt:"Mantenha c\xf3pias criptografadas de documentos importantes.",en:"Keep encrypted copies of important documents.",es:"Guarda copias cifradas de documentos importantes."}]},{id:"negociacoes",title:{pt:"Cuidados em negocia\xe7\xf5es entre usu\xe1rios",en:"Care when dealing with other users",es:"Cuidados en negociaciones entre usuarios"},intro:{pt:"A plataforma conecta pessoas, mas n\xe3o intermedeia pagamentos, alugu\xe9is ou contratos.",en:"The platform connects people but does not mediate payments, rentals or contracts.",es:"La plataforma conecta personas, pero no intermedia pagos, alquileres ni contratos."},items:[{pt:"Nunca envie dinheiro, c\xf3digos de verifica\xe7\xe3o ou senhas para outras pessoas usu\xe1rias.",en:"Never send money, verification codes or passwords to other users.",es:"Nunca env\xedes dinero, c\xf3digos de verificaci\xf3n ni contrase\xf1as a otras personas usuarias."},{pt:"Desconfie de ofertas de moradia ou trabalho feitas por mensagem privada sem refer\xeancias.",en:"Be wary of housing or job offers made by private message without references.",es:"Desconf\xeda de ofertas de vivienda o trabajo hechas por mensaje privado sin referencias."},{pt:"Em encontros presenciais, escolha locais p\xfablicos e avise algu\xe9m de confian\xe7a.",en:"For in-person meetups, choose public places and let someone you trust know.",es:"En encuentros presenciales, elige lugares p\xfablicos y avisa a alguien de confianza."},{pt:"Registre acordos por escrito e use canais com prote\xe7\xe3o ao consumidor.",en:"Put agreements in writing and use channels with consumer protection.",es:"Registra acuerdos por escrito y usa canales con protecci\xf3n al consumidor."}]},{id:"regras",title:{pt:"Regras de conviv\xeancia da comunidade",en:"Community guidelines",es:"Reglas de convivencia de la comunidad"},intro:{pt:"Queremos um espa\xe7o acolhedor para pessoas de diferentes origens, corpos, idiomas e realidades.",en:"We want a welcoming space for people of different backgrounds, bodies, languages and realities.",es:"Queremos un espacio acogedor para personas de distintos or\xedgenes, cuerpos, idiomas y realidades."},items:[{pt:"Respeite todas as pessoas. Discrimina\xe7\xe3o, ass\xe9dio e discurso de \xf3dio resultam em remo\xe7\xe3o.",en:"Respect everyone. Discrimination, harassment and hate speech lead to removal.",es:"Respeta a todas las personas. La discriminaci\xf3n, el acoso y el discurso de odio implican expulsi\xf3n."},{pt:"Compartilhe experi\xeancias, n\xe3o promessas. Evite vender o nomadismo como solu\xe7\xe3o f\xe1cil.",en:"Share experiences, not promises. Avoid selling nomadism as an easy fix.",es:"Comparte experiencias, no promesas. Evita vender el nomadismo como una soluci\xf3n f\xe1cil."},{pt:"Indique fontes quando falar de vistos, impostos ou sa\xfade.",en:"Cite sources when talking about visas, taxes or health.",es:"Indica fuentes cuando hables de visados, impuestos o salud."},{pt:"Considere o impacto da sua presen\xe7a nas comunidades locais.",en:"Consider the impact of your presence on local communities.",es:"Considera el impacto de tu presencia en las comunidades locales."},{pt:"Publicidade e links de afiliados passam por revis\xe3o da modera\xe7\xe3o.",en:"Advertising and affiliate links are reviewed by moderators.",es:"La publicidad y los enlaces de afiliados pasan por revisi\xf3n de moderaci\xf3n."}]}],i=[{title:{pt:"Conte\xfado curado, n\xe3o definitivo",en:"Curated, not definitive, content",es:"Contenido curado, no definitivo"},text:{pt:"Organizamos informa\xe7\xf5es para orientar a pesquisa, mas elas n\xe3o substituem fontes oficiais nem profissionais especializados.",en:"We organize information to guide your research, but it doesn't replace official sources or specialized professionals.",es:"Organizamos informaci\xf3n para orientar la b\xfasqueda, pero no reemplaza fuentes oficiales ni profesionales especializados."}},{title:{pt:"Selo de fonte verificada",en:"Verified source badge",es:"Sello de fuente verificada"},text:{pt:"Nesta vers\xe3o, o selo indica apenas vagas de demonstra\xe7\xe3o previamente definidas como curadas. N\xe3o h\xe1 verifica\xe7\xe3o de empresas reais.",en:"In this version, the badge only marks demo jobs previously defined as curated. No real companies are verified.",es:"En esta versi\xf3n, el sello indica solo vacantes de demostraci\xf3n definidas previamente como curadas. No se verifican empresas reales."}},{title:{pt:"Sem coleta autom\xe1tica de dados",en:"No automated data collection",es:"Sin recolecci\xf3n autom\xe1tica de datos"},text:{pt:"N\xe3o fazemos scraping de vagas, hospedagens ou perfis de outros sites. Todo conte\xfado de exemplo foi escrito para a demonstra\xe7\xe3o.",en:"We don't scrape jobs, listings or profiles from other sites. All sample content was written for the demo.",es:"No hacemos scraping de vacantes, alojamientos ni perfiles de otros sitios. Todo el contenido de ejemplo fue escrito para la demostraci\xf3n."}},{title:{pt:"Seus dados ficam com voc\xea",en:"Your data stays with you",es:"Tus datos se quedan contigo"},text:{pt:"Perfil, planejamento e mensagens ficam salvos no seu navegador. Voc\xea pode exportar ou apagar tudo no perfil.",en:"Your profile, planning and messages are stored in your browser. You can export or delete everything from your profile.",es:"Tu perfil, planificaci\xf3n y mensajes se guardan en tu navegador. Puedes exportar o borrar todo desde el perfil."}}],n={terms:{id:"termos",updatedAt:"2026-11-01",sections:[{title:{pt:"1. Sobre a plataforma",en:"1. About the platform",es:"1. Sobre la plataforma"},paragraphs:[{pt:"O Conectados pelo Mundo \xe9 um espa\xe7o de informa\xe7\xe3o, planejamento e comunidade para pessoas interessadas no trabalho remoto e no nomadismo digital.",en:"Conectados pelo Mundo is a space for information, planning and community for people interested in remote work and digital nomadism.",es:"Conectados pelo Mundo es un espacio de informaci\xf3n, planificaci\xf3n y comunidad para personas interesadas en el trabajo remoto y el nomadismo digital."},{pt:"Esta vers\xe3o \xe9 uma demonstra\xe7\xe3o: vagas, destinos, perfis e conversas s\xe3o fict\xedcios.",en:"This version is a demo: jobs, destinations, profiles and conversations are fictional.",es:"Esta versi\xf3n es una demostraci\xf3n: vacantes, destinos, perfiles y conversaciones son ficticios."}]},{title:{pt:"2. Responsabilidades de quem usa",en:"2. User responsibilities",es:"2. Responsabilidades de quien usa"},paragraphs:[{pt:"Voc\xea \xe9 respons\xe1vel pelas informa\xe7\xf5es que publica e pelas decis\xf5es que toma com base no conte\xfado da plataforma.",en:"You are responsible for the information you post and the decisions you make based on the platform's content.",es:"Eres responsable de la informaci\xf3n que publicas y de las decisiones que tomas con base en el contenido de la plataforma."},{pt:"Quest\xf5es jur\xeddicas, fiscais, migrat\xf3rias e de sa\xfade devem ser confirmadas com fontes oficiais e profissionais habilitados.",en:"Legal, tax, immigration and health matters must be confirmed with official sources and licensed professionals.",es:"Las cuestiones jur\xeddicas, fiscales, migratorias y de salud deben confirmarse con fuentes oficiales y profesionales habilitados."}]},{title:{pt:"3. Conte\xfado da comunidade",en:"3. Community content",es:"3. Contenido de la comunidad"},paragraphs:[{pt:"Publica\xe7\xf5es devem seguir as regras de conviv\xeancia. Conte\xfados com links externos, contatos ou pedidos de pagamento podem passar por revis\xe3o.",en:"Posts must follow the community guidelines. Content with external links, contacts or payment requests may be reviewed.",es:"Las publicaciones deben seguir las reglas de convivencia. Los contenidos con enlaces externos, contactos o pedidos de pago pueden ser revisados."}]},{title:{pt:"4. Limita\xe7\xf5es",en:"4. Limitations",es:"4. Limitaciones"},paragraphs:[{pt:"A plataforma n\xe3o intermedeia contratos de trabalho, alugu\xe9is ou pagamentos entre pessoas usu\xe1rias.",en:"The platform does not mediate employment contracts, rentals or payments between users.",es:"La plataforma no intermedia contratos de trabajo, alquileres ni pagos entre personas usuarias."}]}]},privacy:{id:"privacidade",updatedAt:"2026-11-01",sections:[{title:{pt:"1. Quais dados usamos",en:"1. What data we use",es:"1. Qu\xe9 datos usamos"},paragraphs:[{pt:"Nesta vers\xe3o, os dados de perfil, planejamento, itens salvos, publica\xe7\xf5es e mensagens ficam armazenados apenas no seu navegador (localStorage).",en:"In this version, profile, planning, saved items, posts and messages are stored only in your browser (localStorage).",es:"En esta versi\xf3n, los datos de perfil, planificaci\xf3n, guardados, publicaciones y mensajes se almacenan solo en tu navegador (localStorage)."}]},{title:{pt:"2. Para que usamos",en:"2. Why we use it",es:"2. Para qu\xe9 los usamos"},paragraphs:[{pt:"As respostas do onboarding servem para personalizar sugest\xf5es, pr\xf3ximos passos e oportunidades exibidas no painel.",en:"Onboarding answers are used to personalize suggestions, next steps and opportunities shown on your dashboard.",es:"Las respuestas del onboarding sirven para personalizar sugerencias, pr\xf3ximos pasos y oportunidades del panel."}]},{title:{pt:"3. Seus direitos e controles",en:"3. Your rights and controls",es:"3. Tus derechos y controles"},paragraphs:[{pt:"Voc\xea pode exportar seus dados em JSON ou apag\xe1-los a qualquer momento na p\xe1gina de perfil. Tamb\xe9m pode definir quem v\xea seu perfil e se aceita mensagens.",en:"You can export your data as JSON or delete it at any time on the profile page. You can also choose who sees your profile and whether you accept messages.",es:"Puedes exportar tus datos en JSON o borrarlos en cualquier momento desde el perfil. Tambi\xe9n puedes definir qui\xe9n ve tu perfil y si aceptas mensajes."}]},{title:{pt:"4. Integra\xe7\xf5es futuras",en:"4. Future integrations",es:"4. Integraciones futuras"},paragraphs:[{pt:"Caso a plataforma passe a usar servidores, tradu\xe7\xe3o autom\xe1tica ou login, esta pol\xedtica ser\xe1 atualizada antes da coleta de qualquer novo dado, em conformidade com a LGPD.",en:"If the platform starts using servers, automatic translation or login, this policy will be updated before any new data is collected, in line with Brazil's LGPD.",es:"Si la plataforma pasa a usar servidores, traducci\xf3n autom\xe1tica o inicio de sesi\xf3n, esta pol\xedtica se actualizar\xe1 antes de recopilar nuevos datos, de acuerdo con la LGPD brasile\xf1a."}]}]}}}}]);